/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: setSliderBounds
 * Tests
 *   - previews pointer time without seeking and commits the final position on release
 *   - keeps buffered gaps distinct from played progress and clears stale ranges
 *   - does not paint buffered progress without a finite known duration
 *   - commits native keyboard range changes and disables unknown durations
 * @end-catalog */

import { fireEvent, render, screen } from '@testing-library/react';

import { SeekSlider } from './SeekSlider';

beforeEach(() => {
  vi.stubGlobal('PointerEvent', MouseEvent);
});

const setSliderBounds = (slider: HTMLElement) => {
  vi.spyOn(slider, 'getBoundingClientRect').mockReturnValue({
    bottom: 24,
    height: 4,
    left: 0,
    right: 100,
    top: 20,
    width: 100,
    x: 0,
    y: 20,
    toJSON: () => ({})
  });
};

test('previews pointer time without seeking and commits the final position on release', () => {
  const onSeek = vi.fn();
  render(<SeekSlider currentTime={1} duration={100} bufferedRanges={[{ start: 0, end: 60 }]} itemKey="track-1" onSeek={onSeek} />);
  const slider = screen.getByRole('slider', { name: 'Playback position' });
  setSliderBounds(slider);

  fireEvent.pointerDown(slider, {
    button: 2,
    clientX: 90,
    pointerId: 1,
    pointerType: 'mouse'
  });
  fireEvent.pointerUp(slider, {
    button: 2,
    clientX: 90,
    pointerId: 1,
    pointerType: 'mouse'
  });
  expect(onSeek).not.toHaveBeenCalled();

  fireEvent.pointerMove(slider, { clientX: 50, pointerId: 1 });
  expect(screen.getByText('0:50')).toBeInTheDocument();
  expect(slider).toHaveValue('1');
  expect(onSeek).not.toHaveBeenCalled();

  fireEvent.pointerDown(slider, { button: 0, clientX: 20, pointerId: 1 });
  fireEvent.pointerMove(slider, { clientX: 75, pointerId: 1 });
  expect(slider).toHaveValue('75');
  expect(onSeek).not.toHaveBeenCalled();
  fireEvent.pointerUp(slider, { clientX: 75, pointerId: 1 });
  expect(onSeek).toHaveBeenCalledOnce();
  expect(onSeek).toHaveBeenCalledWith(75);
});

test('keeps buffered gaps distinct from played progress and clears stale ranges', () => {
  const onSeek = vi.fn();
  const { rerender } = render(
    <SeekSlider currentTime={10} duration={100} bufferedRanges={[{ start: 0, end: 40 }, { start: 60, end: 80 }]} itemKey="track-1" onSeek={onSeek} />
  );
  const slider = screen.getByRole('slider', { name: 'Playback position' });
  const track = slider.parentElement!;
  expect(track.style.getPropertyValue('--seek-progress')).toBe('10%');
  expect(track.style.getPropertyValue('--seek-buffered')).toBe(
    'linear-gradient(to right, transparent 0%, var(--color-text-subtle) 0% 40%, transparent 40%, transparent 60%, var(--color-text-subtle) 60% 80%, transparent 80%)'
  );
  expect(slider).toHaveValue('10');
  expect(onSeek).not.toHaveBeenCalled();

  rerender(<SeekSlider currentTime={10} duration={100} bufferedRanges={[{ start: 60, end: 90 }]} itemKey="track-1" onSeek={onSeek} />);
  expect(track.style.getPropertyValue('--seek-buffered')).toBe(
    'linear-gradient(to right, transparent 60%, var(--color-text-subtle) 60% 90%, transparent 90%)'
  );
  expect(track.style.getPropertyValue('--seek-progress')).toBe('10%');

  rerender(<SeekSlider currentTime={0} duration={100} itemKey="track-2" onSeek={onSeek} />);
  expect(track.style.getPropertyValue('--seek-buffered')).toBe('none');
  expect(track.style.getPropertyValue('--seek-progress')).toBe('0%');
});

test('does not paint buffered progress without a finite known duration', () => {
  const ranges = [{ start: 0, end: 40 }];
  const { rerender } = render(<SeekSlider currentTime={0} duration={0} bufferedRanges={ranges} onSeek={vi.fn()} />);
  const slider = screen.getByRole('slider', { name: 'Playback position' });
  expect(slider).toBeDisabled();
  expect(slider.parentElement!.style.getPropertyValue('--seek-buffered')).toBe('none');
  rerender(<SeekSlider currentTime={0} duration={Infinity} bufferedRanges={ranges} onSeek={vi.fn()} />);
  expect(slider).toBeDisabled();
  expect(slider.parentElement!.style.getPropertyValue('--seek-buffered')).toBe('none');
});

test('commits native keyboard range changes and disables unknown durations', () => {
  const onSeek = vi.fn();
  const { rerender } = render(
    <SeekSlider currentTime={10} duration={100} itemKey="track-1" onSeek={onSeek} />
  );
  const slider = screen.getByRole('slider', { name: 'Playback position' });

  fireEvent.change(slider, { target: { value: '35' } });
  expect(onSeek).toHaveBeenCalledWith(35);
  rerender(<SeekSlider currentTime={35} duration={100} itemKey="track-1" onSeek={onSeek} />);
  expect(slider).toHaveAttribute('aria-valuetext', '0:35');

  rerender(<SeekSlider currentTime={0} duration={0} itemKey="track-2" onSeek={onSeek} />);
  expect(slider).toBeDisabled();
  expect(screen.queryByText('0:35')).not.toBeInTheDocument();
});
